insert into kafaa_starter_lessons (id, track, sort, title_en, title_ar, summary_en, summary_ar, points, self_check, links, induction_module_id, sources, as_of, listed) values
('sl-ai-what', 'ai', 1, 'What AI is, and what it is not', 'ما هو الذكاء الاصطناعي، وما ليس هو', 'AI tools find patterns in large amounts of data and use them to predict, sort or write. They do not understand the world the way people do, and they can be confidently wrong.', 'تكتشف أدوات الذكاء الاصطناعي الأنماط في كميات كبيرة من البيانات وتستخدمها للتنبؤ أو التصنيف أو الكتابة. لكنها لا تفهم العالم كما يفهمه الناس، وقد تخطئ وهي واثقة.', '[{"en":"AI learns patterns from examples, so a situation that looks new can confuse it.","ar":"يتعلم الذكاء الاصطناعي الأنماط من الأمثلة، لذلك قد يرتبك أمام موقف يبدو جديداً."},{"en":"Generative AI writes text and makes images by predicting what usually comes next.","ar":"يكتب الذكاء الاصطناعي التوليدي النصوص وينشئ الصور بالتنبؤ بما يأتي عادةً بعد ذلك."},{"en":"A person stays responsible for every decision that uses an AI output.","ar":"يبقى الإنسان مسؤولاً عن كل قرار يستخدم ناتج الذكاء الاصطناعي."}]'::jsonb, '{"prompt_en":"A chatbot gives you a confident answer about a plant procedure. What do you do?","prompt_ar":"يعطيك روبوت محادثة إجابة واثقة عن إجراء في المحطة. ماذا تفعل؟","options":[{"en":"Use it: AI answers are checked before you see them","ar":"أستخدمها: إجابات الذكاء الاصطناعي تُراجع قبل أن أراها"},{"en":"Check it against the approved procedure and ask a qualified person","ar":"أتحقق منها مقابل الإجراء المعتمد وأسأل شخصاً مؤهلاً"},{"en":"Stop using every AI tool","ar":"أتوقف عن استخدام كل أدوات الذكاء الاصطناعي"}],"correct":1,"explain_en":"AI can be confidently wrong. In a nuclear plant the approved procedure and qualified people decide; AI only helps.","explain_ar":"قد يخطئ الذكاء الاصطناعي وهو واثق. في المحطة النووية يقرر الإجراء المعتمد والأشخاص المؤهلون؛ والذكاء الاصطناعي يساعد فقط."}'::jsonb, '[{"to":"/learn/ai-fluency","label_en":"See the AI Fluency Ladder","label_ar":"اطّلع على سلّم الطلاقة في الذكاء الاصطناعي"}]'::jsonb, 'ind-ai-basics', '[{"label":"UNESCO · AI competency framework for students (2024), summary via the GCED Clearinghouse","url":"https://gcedclearinghouse.org/en/node/146447","publisher":"UNESCO","as_of":"2026-10-10","secondary":true},{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","publisher":"IAEA","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-ai-check', 'ai', 2, 'Checking what AI tells you', 'التحقق مما يخبرك به الذكاء الاصطناعي', 'Good AI users check an output before they use it: they look for the source, compare it with what they know and ask when they are unsure.', 'يتحقق المستخدم الجيد للذكاء الاصطناعي من الناتج قبل استخدامه: يبحث عن المصدر، ويقارنه بما يعرفه، ويسأل عندما لا يكون متأكداً.', '[{"en":"Ask where a fact comes from, then open the source yourself.","ar":"اسأل من أين جاءت المعلومة، ثم افتح المصدر بنفسك."},{"en":"Compare the answer with an approved document or an expert.","ar":"قارن الإجابة بوثيقة معتمدة أو بخبير."},{"en":"Say clearly when AI helped with your work.","ar":"وضّح متى ساعدك الذكاء الاصطناعي في عملك."}]'::jsonb, '{"prompt_en":"Which habit makes AI use safer?","prompt_ar":"أي عادة تجعل استخدام الذكاء الاصطناعي أكثر أماناً؟","options":[{"en":"Copying the first answer","ar":"نسخ الإجابة الأولى"},{"en":"Checking the answer against a trusted source","ar":"التحقق من الإجابة مقابل مصدر موثوق"},{"en":"Asking again until the answer sounds right","ar":"إعادة السؤال حتى تبدو الإجابة صحيحة"}],"correct":1,"explain_en":"A trusted source is the check; asking again only gives you another prediction.","explain_ar":"المصدر الموثوق هو أداة التحقق؛ أما إعادة السؤال فتعطيك تنبؤاً آخر فقط."}'::jsonb, '[{"to":"/learn/ai-fluency","label_en":"See the AI Fluency Ladder","label_ar":"اطّلع على سلّم الطلاقة في الذكاء الاصطناعي"}]'::jsonb, 'ind-ai-responsible', '[{"label":"European Commission · Living repository of AI literacy practices (AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","publisher":"European Commission","as_of":"2026-10-10"},{"label":"UNESCO · AI competency framework for students (2024), summary via the GCED Clearinghouse","url":"https://gcedclearinghouse.org/en/node/146447","publisher":"UNESCO","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-ai-fair', 'ai', 3, 'Fairness, privacy and your data', 'العدالة والخصوصية وبياناتك', 'AI systems can repeat unfair patterns from their training data, and anything you type into a public tool may leave your control.', 'قد تكرر أنظمة الذكاء الاصطناعي أنماطاً غير عادلة من بيانات تدريبها، وأي شيء تكتبه في أداة عامة قد يخرج عن سيطرتك.', '[{"en":"Never paste personal, confidential or security information into a public AI tool.","ar":"لا تلصق أبداً معلومات شخصية أو سرية أو أمنية في أداة ذكاء اصطناعي عامة."},{"en":"Results can be biased when the training data were unbalanced.","ar":"قد تكون النتائج متحيزة عندما تكون بيانات التدريب غير متوازنة."},{"en":"Respect other people''s work and say what you used.","ar":"احترم عمل الآخرين ووضّح ما استخدمته."}]'::jsonb, '{"prompt_en":"You want an AI tool to summarise a document that lists people''s names and ID numbers. What is right?","prompt_ar":"تريد من أداة ذكاء اصطناعي تلخيص وثيقة فيها أسماء أشخاص وأرقام هوياتهم. ما التصرف الصحيح؟","options":[{"en":"Paste it into any free chatbot","ar":"ألصقها في أي روبوت محادثة مجاني"},{"en":"Remove the personal data or use an approved tool, and ask first","ar":"أحذف البيانات الشخصية أو أستخدم أداة معتمدة، وأسأل أولاً"},{"en":"Ask a friend to paste it for you","ar":"أطلب من صديق أن يلصقها بدلاً مني"}],"correct":1,"explain_en":"Personal data stays protected: remove it, or use a tool your organisation has approved for it.","explain_ar":"تبقى البيانات الشخصية محمية: احذفها، أو استخدم أداة اعتمدتها مؤسستك لهذا الغرض."}'::jsonb, '[{"to":"/learn/ai-fluency","label_en":"See the AI Fluency Ladder","label_ar":"اطّلع على سلّم الطلاقة في الذكاء الاصطناعي"}]'::jsonb, 'ind-ai-responsible', '[{"label":"UNESCO · AI competency framework for students (2024), summary via the GCED Clearinghouse","url":"https://gcedclearinghouse.org/en/node/146447","publisher":"UNESCO","as_of":"2026-10-10","secondary":true},{"label":"European Commission · Living repository of AI literacy practices (AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","publisher":"European Commission","as_of":"2026-10-10"}]'::jsonb, '2026-10-10', true),
('sl-ai-uae', 'ai', 4, 'Learning AI in the UAE', 'تعلّم الذكاء الاصطناعي في الإمارات', 'The UAE treats AI literacy as national policy: the National AI Strategy 2031, AI inside the school curriculum from the 2025-26 academic year, and practical AI training for government employees in Abu Dhabi (AiNative).', 'تتعامل الإمارات مع الإلمام بالذكاء الاصطناعي كسياسة وطنية: الاستراتيجية الوطنية للذكاء الاصطناعي 2031، والذكاء الاصطناعي ضمن المنهج المدرسي منذ العام الدراسي 2025-2026، والتدريب العملي لموظفي حكومة أبوظبي (برنامج AiNative).', '[{"en":"AI is taught in UAE schools from the 2025-26 academic year, inside existing lessons.","ar":"يُدرَّس الذكاء الاصطناعي في مدارس الإمارات منذ العام الدراسي 2025-2026 ضمن الحصص القائمة."},{"en":"Abu Dhabi''s Department of Government Enablement runs AiNative, practical AI training for government employees.","ar":"تدير دائرة التمكين الحكومي في أبوظبي برنامج AiNative للتدريب العملي على الذكاء الاصطناعي لموظفي الحكومة."},{"en":"Because school leavers now learn AI basics, ENEC''s induction can skip what a new intake already knows.","ar":"لأن خريجي المدارس يتعلمون الآن أساسيات الذكاء الاصطناعي، يمكن لبرنامج التهيئة في ENEC تخطي ما تعرفه الدفعة الجديدة مسبقاً."}]'::jsonb, '{"prompt_en":"Why does Kafa''a keep induction baselines by intake year?","prompt_ar":"لماذا تحتفظ كفاءة بخطوط أساس للتهيئة حسب سنة الالتحاق؟","options":[{"en":"To compare new joiners with each other","ar":"لمقارنة المنضمين الجدد ببعضهم"},{"en":"So induction does not re-teach what an intake already learned at school or university","ar":"حتى لا تعيد التهيئة تدريس ما تعلمته الدفعة في المدرسة أو الجامعة"},{"en":"To decide who gets a job","ar":"لتحديد من يحصل على الوظيفة"}],"correct":1,"explain_en":"Baselines describe a whole intake, never one person, and they only shorten induction: nobody is compared or selected by them.","explain_ar":"تصف خطوط الأساس دفعة كاملة وليس شخصاً واحداً، وهي تختصر التهيئة فقط: لا يُقارَن أحد ولا يُختار بناءً عليها."}'::jsonb, '[{"to":"/learn/ai-fluency","label_en":"See the AI Fluency Ladder","label_ar":"اطّلع على سلّم الطلاقة في الذكاء الاصطناعي"}]'::jsonb, 'ind-ai-basics', '[{"label":"Middle East AI News · UAE moves to embed AI learning across the entire school system (2025)","url":"https://www.middleeastainews.com/p/uae-rolls-out-ai-school-curriculum","publisher":"Middle East AI News","as_of":"2026-10-10","secondary":true},{"label":"Abu Dhabi Department of Government Enablement · What we do","url":"https://dge.gov.ae/en/what-we-do","publisher":"DGE Abu Dhabi","as_of":"2026-10-10"},{"label":"Khaleej Times · Abu Dhabi to train government employees in AI by 2027 (AiNative)","url":"https://www.khaleejtimes.com/abu-dhabi-train-23000-government-employees-ai-by-2027","publisher":"Khaleej Times","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-ai-plant', 'ai', 5, 'AI at a nuclear plant: people stay in charge', 'الذكاء الاصطناعي في المحطة النووية: يبقى الإنسان صاحب القرار', 'Nuclear operators use AI and digital twins to analyse plant data, for example to spot equipment that may need maintenance. Qualified people still make the safety decisions.', 'يستخدم مشغلو المحطات النووية الذكاء الاصطناعي والتوائم الرقمية لتحليل بيانات المحطة، مثل رصد المعدات التي قد تحتاج إلى صيانة. ويبقى الأشخاص المؤهلون أصحاب قرارات السلامة.', '[{"en":"A digital twin is a computer copy of real equipment that helps analyse plant data.","ar":"التوأم الرقمي نسخة حاسوبية من معدات حقيقية تساعد على تحليل بيانات المحطة."},{"en":"Predictive maintenance uses data to plan work before a part fails.","ar":"تستخدم الصيانة التنبؤية البيانات لتخطيط العمل قبل أن يتعطل الجزء."},{"en":"Safety-related decisions always need qualified human review.","ar":"تحتاج القرارات المتعلقة بالسلامة دائماً إلى مراجعة بشرية مؤهلة."}]'::jsonb, '{"prompt_en":"An AI tool flags a possible problem with a pump. Who decides what to do?","prompt_ar":"تنبّه أداة ذكاء اصطناعي إلى مشكلة محتملة في مضخة. من يقرر ما يجب فعله؟","options":[{"en":"The AI tool","ar":"أداة الذكاء الاصطناعي"},{"en":"Qualified people, using the AI alert as one input","ar":"الأشخاص المؤهلون، مع اعتبار تنبيه الذكاء الاصطناعي أحد المدخلات"},{"en":"Whoever sees the alert first","ar":"أول من يرى التنبيه"}],"correct":1,"explain_en":"The alert is information. Qualified people check it and decide, following procedures.","explain_ar":"التنبيه معلومة. يتحقق منها الأشخاص المؤهلون ويقررون وفق الإجراءات."}'::jsonb, '[{"to":"/learn/ai-fluency","label_en":"See the AI Fluency Ladder","label_ar":"اطّلع على سلّم الطلاقة في الذكاء الاصطناعي"}]'::jsonb, 'ind-ai-enec', '[{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","publisher":"IAEA","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-smr-what', 'smr', 6, 'What is a small modular reactor?', 'ما هو المفاعل النمطي الصغير؟', 'Small modular reactors (SMRs) are smaller nuclear power units designed around factory-made modules. Several designs exist, and countries such as Canada are already training people for them.', 'المفاعلات النمطية الصغيرة وحدات أصغر لتوليد الطاقة النووية تقوم على وحدات تُصنع في المصانع. توجد عدة تصاميم منها، وتدرّب دول مثل كندا الكوادر عليها منذ الآن.', '[{"en":"Main parts are built in a factory as modules, then assembled.","ar":"تُصنع الأجزاء الرئيسية في المصنع على شكل وحدات، ثم تُجمَّع."},{"en":"In Canada, GE Vernova Hitachi opened an SMR engineering and service centre in Ontario that includes training.","ar":"في كندا، افتتحت شركة جي إي فيرنوفا هيتاشي مركزاً لهندسة وخدمات المفاعلات النمطية الصغيرة في أونتاريو يشمل التدريب."},{"en":"University simulators let students act as control-room operators of a multi-unit SMR plant (NuScale E2 Centers).","ar":"تتيح أجهزة المحاكاة في الجامعات للطلاب أداء دور مشغلي غرفة التحكم في محطة متعددة الوحدات (مراكز E2 من نيوسكيل)."}]'::jsonb, '{"prompt_en":"What does \"modular\" mean in small modular reactor?","prompt_ar":"ماذا تعني كلمة \"النمطي\" في المفاعل النمطي الصغير؟","options":[{"en":"Main parts are built in a factory as modules","ar":"تُصنع الأجزاء الرئيسية في المصنع على شكل وحدات"},{"en":"The reactor is moved every week","ar":"يُنقل المفاعل كل أسبوع"},{"en":"It makes heat but never electricity","ar":"ينتج الحرارة ولا ينتج الكهرباء أبداً"}],"correct":0,"explain_en":"Modular means factory-built modules. This is a learning topic only: no deployment decision is implied.","explain_ar":"النمطي يعني وحدات مصنّعة في المصنع. هذا موضوع للتعلم فقط: لا يعني أي قرار بالنشر."}'::jsonb, '[{"to":"/careers/next-gen","label_en":"What changes for each Barakah role (next-generation careers)","label_ar":"ما الذي يتغير في كل وظيفة في براكة (وظائف الجيل القادم)"}]'::jsonb, 'ind-smr', '[{"label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","publisher":"GE Vernova","as_of":"2026-10-10","secondary":true},{"label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","publisher":"Oregon State University","as_of":"2026-10-10","secondary":true},{"label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","publisher":"American Nuclear Society","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-smr-skills', 'smr', 7, 'What changes, and what stays the same', 'ما الذي يتغير، وما الذي يبقى كما هو', 'Most Barakah skills carry over to newer reactor designs: safety culture, procedures, radiation protection and plant fundamentals. What changes is mainly running several units, digital controls, passive safety features and maintenance.', 'تنتقل معظم مهارات براكة إلى تصاميم المفاعلات الأحدث: ثقافة السلامة والإجراءات والوقاية من الإشعاع وأساسيات المحطة. وما يتغير أساساً هو تشغيل عدة وحدات والتحكم الرقمي وخصائص السلامة الذاتية والصيانة.', '[{"en":"Carries over: safety culture, procedure use, radiation protection and plant fundamentals.","ar":"ينتقل كما هو: ثقافة السلامة واستخدام الإجراءات والوقاية من الإشعاع وأساسيات المحطة."},{"en":"Changes: multi-unit operation, digital instrumentation and control, passive safety and different maintenance regimes.","ar":"يتغير: تشغيل عدة وحدات، والأجهزة والتحكم الرقمي، والسلامة الذاتية، وأنظمة صيانة مختلفة."},{"en":"Every Barakah role has its own change summary on the next-generation careers page.","ar":"لكل وظيفة في براكة ملخص للتغيير في صفحة وظائف الجيل القادم."}]'::jsonb, '{"prompt_en":"Which of these carries over from Barakah to a newer reactor design?","prompt_ar":"أي مما يلي ينتقل من براكة إلى تصميم مفاعل أحدث؟","options":[{"en":"Safety culture and procedure use","ar":"ثقافة السلامة واستخدام الإجراءات"},{"en":"The exact control-room layout","ar":"التصميم الدقيق لغرفة التحكم"},{"en":"The same maintenance schedule","ar":"جدول الصيانة نفسه"}],"correct":0,"explain_en":"Safety culture and procedure use travel with you; layouts and maintenance regimes change with the design.","explain_ar":"ثقافة السلامة واستخدام الإجراءات ترافقك دائماً؛ أما التصاميم وأنظمة الصيانة فتتغير بتغير التصميم."}'::jsonb, '[{"to":"/careers/next-gen","label_en":"What changes for each Barakah role (next-generation careers)","label_ar":"ما الذي يتغير في كل وظيفة في براكة (وظائف الجيل القادم)"}]'::jsonb, 'ind-smr', '[{"label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","publisher":"American Nuclear Society","as_of":"2026-10-10","secondary":true},{"label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","publisher":"GE Vernova","as_of":"2026-10-10","secondary":true}]'::jsonb, '2026-10-10', true),
('sl-smr-careers', 'smr', 8, 'Nuclear careers from school to young professional', 'المسار المهني النووي من المدرسة إلى المهني الشاب', 'The OECD Nuclear Energy Agency''s Plan 2035 aims to grow the nuclear workforce from secondary school through trade school and university to young professionals, with three pathways: Inspire, Mentor and Network.', 'تهدف خطة 2035 لوكالة الطاقة النووية التابعة لمنظمة التعاون الاقتصادي والتنمية إلى تنمية القوى العاملة النووية من المدرسة الثانوية مروراً بالتعليم المهني والجامعة وصولاً إلى المهنيين الشباب، عبر ثلاثة مسارات: الإلهام والإرشاد والتواصل.', '[{"en":"Inspire: outreach resources and video lectures for schools.","ar":"الإلهام: موارد توعوية ومحاضرات مصورة للمدارس."},{"en":"Mentor: mentoring workshops and a global internship programme.","ar":"الإرشاد: ورش إرشاد وبرنامج عالمي للتدريب الداخلي."},{"en":"Network: role models, educators and alumni of young-talent programmes.","ar":"التواصل: قدوات ومعلمون وخريجو برامج المواهب الشابة."}]'::jsonb, '{"prompt_en":"Which Plan 2035 pathway is about reaching schools?","prompt_ar":"أي مسار في خطة 2035 يهتم بالوصول إلى المدارس؟","options":[{"en":"Inspire","ar":"الإلهام"},{"en":"Mentor","ar":"الإرشاد"},{"en":"Network","ar":"التواصل"}],"correct":0,"explain_en":"Inspire is the outreach pathway: exhibits, online resources and lectures for schools.","explain_ar":"الإلهام هو مسار التوعية: المعارض والموارد الإلكترونية والمحاضرات للمدارس."}'::jsonb, '[{"to":"/careers/next-gen","label_en":"What changes for each Barakah role (next-generation careers)","label_ar":"ما الذي يتغير في كل وظيفة في براكة (وظائف الجيل القادم)"},{"to":"/pathways/journey","label_en":"Back to your journey board","label_ar":"العودة إلى لوحة رحلتك"}]'::jsonb, 'ind-smr', '[{"label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","publisher":"OECD Nuclear Energy Agency","as_of":"2026-10-10"}]'::jsonb, '2026-10-10', true)
insert into kafaa_tag_links (id, tag_id, target_table, target_id, note_en, note_ar, active, created_by, created_at, updated_by, updated_at) values
('tl:nt-jahiz:wallet_targets:wt-core-five', 'nt-jahiz', 'wallet_targets', 'wt-core-five', 'The core-five Future Skills Wallet is the whole-workforce future-skills goal, a dated leadership target in the spirit of Jahiz.', 'محفظة مهارات المستقبل بمهاراتها الخمس الأساسية هي هدف مهارات المستقبل لجميع القوى العاملة، وهدف قيادي مؤرخ بروح منصة جاهز.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('tl:nt-ai-2031:wallet_targets:wt-core-five', 'nt-ai-2031', 'wallet_targets', 'wt-core-five', 'AI fluency at Practitioner level is one of the five wallet items, so the wallet target serves the AI strategy.', 'الطلاقة في الذكاء الاصطناعي بمستوى ممارِس هي أحد عناصر المحفظة الخمسة، لذا يخدم هدف المحفظة استراتيجية الذكاء الاصطناعي.', true, 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z')
